public DefaultParser(MediaTypeRegistry registry, ServiceLoader loader, Collection<Class<? extends Parser>> excludeParsers) {
    super(registry, getDefaultParsers(loader, new DefaultEncodingDetector(loader), new CompositeRenderer(loader), excludeParsers));
    this.loader = loader;
    this.excludedClasses = excludeParsers != null ? Collections.unmodifiableCollection(new ArrayList<>(excludeParsers)) : Collections.emptySet();
}
